window.__KB = {"email":"abhishek87@live.in","starters":["What is his total experience?","What has he built?","Has he built AI agents?","What is his tech stack?"],"entries":[{"id":"experience-total","title":"Total experience","keys":["experience","years","how long","total experience","career","seniority","background","how many years"],"ask":["What is the total experience of Abhishek?","How many years of experience does he have?"],"answer":"<p>Abhishek has <b>15+ years</b> of experience designing, delivering and deploying enterprise AI, cloud and digital-transformation solutions across <b>APAC, the Middle East and the UK</b>.</p>\n<p>His most recent roles:</p>\n<ul>\n<li><b>2026–present</b>: Director of AI Solutions Architecture &amp; International Expansion at a multi-region B2B packaging and procurement platform (Singapore)</li>\n<li><b>2024–present</b>: Principal Consultant, Avar Systems (end-to-end development firm)</li>\n<li><b>2023–present</b>: Co-Founder &amp; Head of Product and Technology, Avar Earth</li>\n<li><b>2018–2023</b>: Co-Founder &amp; Head of Product, Whitley Ecom (cross-border eCommerce SaaS)</li>\n<li><b>2015–2018</b>: Senior Manager, International Markets, DTDC Express</li>\n</ul>","links":[["Experience","index.html#experience"]],"follow":["What has he built?","What are his biggest results?"]},{"id":"who","title":"Who Abhishek is","keys":["who","about","introduce","summary","profile","tell me about","overview","abhishek"],"ask":["Who is Abhishek?","Tell me about him","Give me a summary"],"answer":"<p><b>Abhishek Sharma</b> is a Senior AI Solutions Architect and Forward Deployed Engineer based in <b>Singapore</b>, with 15+ years across APAC, the Middle East and the UK.</p>\n<p>He combines hands-on solution architecture (LLM orchestration, RAG, agentic and multi-agent systems, API and data-platform integration on AWS) with client-facing consulting, pre-sales solutioning and end-to-end delivery leadership.</p>\n<p>Recent work includes a <b>7-system production AI ecosystem</b>, an AI-native <b>RFQ &amp; pricing platform</b>, a <b>category-intelligence control plane (CAT AI)</b> and <b>Nexus</b>, an agentic control plane (in progress). Across projects, his systems have removed <b>8 FTE</b> of manual work.</p>","links":[["Selected work","index.html#work"]],"follow":["How does he work?","What is his tech stack?"]},{"id":"current-role","title":"Current role","keys":["current","currently","now","present","job","role","position","director","working","employer","company"],"ask":["What is his current role?","Where does he work now?"],"answer":"<p>Since <b>January 2026</b> he has been <b>Director of AI Solutions Architecture &amp; International Expansion</b> at a multi-region B2B packaging and procurement platform in Singapore, with 65,000+ enterprise customers and operations across India, Singapore, the UAE and the UK. (The portfolio shows this employer under the fictional name “Northwind”.)</p>\n<p>He is accountable for enterprise AI architecture, end-to-end technical delivery and international market expansion. There he built the 7-system AI ecosystem, the RFQ &amp; Pricing Platform, CAT AI, the AI-native corporate website with the PIE agent, and Nexus.</p>\n<p>In parallel he is <b>Principal Consultant at Avar Systems</b> (since January 2024) and <b>Co-Founder of Avar Earth</b> (since November 2023).</p>","links":[["Experience","index.html#experience"]],"follow":["What does he do at Avar Systems?","What is Nexus?"]},{"id":"impact","title":"Biggest results","keys":["results","impact","achievements","achievement","numbers","metrics","outcomes","roi","value","accomplishments","biggest","proud"],"ask":["What are his biggest achievements?","What impact has he delivered?"],"answer":"<p>Headline results from his work:</p>\n<ul>\n<li><b>8 FTE</b> of manual workload removed across the AI systems he has shipped</li>\n<li><b>60%</b> operational efficiency gain from a 7-system production AI ecosystem</li>\n<li><b>80%+</b> improvement in productivity and market-signal coverage for category evaluation (CAT AI)</li>\n<li><b>5+</b> production voice and chat agents for inbound handling, qualification and escalation, targeting a 30% cut in inbound handling cost</li>\n<li><b>35–60%</b> fewer manual touchpoints per client engagement at Avar Systems</li>\n<li><b>10x</b> revenue growth (USD 500K to USD 5M) as co-founder of a cross-border eCommerce SaaS</li>\n<li>Owned <b>USD 3M–5M</b> P&amp;L and drove market entry across <b>25 countries</b></li>\n</ul>","links":[["Selected work","index.html#work"]],"follow":["How many FTEs has he saved?","Tell me about the 7-system AI ecosystem"]},{"id":"fte","title":"FTE and productivity savings","keys":["fte","headcount","manual work","manual workload","saved","savings","productivity","efficiency","automation savings","cost reduction"],"ask":["How many FTEs has he saved?","What productivity gains has he delivered?"],"answer":"<p>Across the AI systems he has shipped, Abhishek’s work has removed <b>8 FTE</b> of manual workload. Productivity highlights:</p>\n<ul>\n<li><b>60%</b> operational efficiency gain from the 7-system AI ecosystem (2+ FTE of that on its own)</li>\n<li><b>80%+</b> productivity and market-signal coverage gain in category evaluation with CAT AI</li>\n<li><b>40%</b> less admin work at Avar Earth, letting a 3-person team deliver 7-person output</li>\n<li><b>35–60%</b> fewer manual touchpoints per Avar Systems client engagement</li>\n<li>Outbound research workload eliminated by an automated C-suite pipeline (10 personalised emails a day across 25+ countries)</li>\n</ul>","links":[["7-system AI ecosystem","work/markai.html"],["CAT AI","work/cat-ai.html"]],"follow":["Has he built AI agents?","What is CAT AI?"]},{"id":"rag","title":"RAG experience","keys":["rag","retrieval","retrieval augmented","knowledge base","vector","embeddings","knowledge system","semantic search"],"ask":["Has he built RAG systems?","Does he have RAG experience?"],"answer":"<p>Yes. Retrieval-Augmented Generation is part of his production work:</p>\n<ul>\n<li>A <b>RAG sales-knowledge system</b> is one of the seven connected systems in the AI ecosystem he architected. It shares one lead record and data layer (Supabase) with the voice, chat and lead-management agents.</li>\n<li>The PIE agent, the Sourcing Assistant in CAT AI and Ask Genie in Avar Genie all answer from the platform’s own data rather than the model’s general knowledge.</li>\n</ul>\n<p>His design principle: build a single source of truth first, so every retrieval and agent reads the same record.</p>","links":[["7-system AI ecosystem","work/markai.html"]],"follow":["Has he built AI agents?","Why a shared data layer?"]},{"id":"agents","title":"AI agents and multi-agent systems","keys":["agents","agent","agentic","multi agent","multi-agent","autonomous","orchestration","ai agents","kill switch","control plane"],"ask":["Has he built AI agents?","What agentic systems has he built?"],"answer":"<p>Agentic systems are central to his work:</p>\n<ul>\n<li><b>7 connected production systems</b>: agentic lead management, voice agents, ad strategy, social automation, a global lead pipeline, RAG sales knowledge and customer escalation, all orchestrated by n8n on one Supabase data layer</li>\n<li><b>5+ production voice and chat agents</b> (Retell AI, GPT-4o) for inbound handling, lead qualification and logistics escalation</li>\n<li>A <b>Monitor / Comms / Insight</b> agent trio for proof-of-delivery and invoice automation, targeting DSO reduction</li>\n<li><b>Nexus</b> (in progress): an agentic control plane that connects every agent and platform, gives management one view, and puts everything behind a single kill switch</li>\n<li>He also ran the architecture retrospective of an 11-agent vendor programme, which traced cascading agent failures to a missing single-source-of-truth data layer</li>\n</ul>","links":[["Nexus","work/nexus.html"],["7-system AI ecosystem","work/markai.html"]],"follow":["What is Nexus?","Tell me about the voice agents"]},{"id":"voice","title":"Voice and chat agents","keys":["voice","voice agent","voice agents","chat agent","chatbot","call","retell","retell ai","vapi","elevenlabs","pie","packaging intelligence expert","inbound","conversational"],"ask":["Tell me about the voice agents","What is PIE?"],"answer":"<p>He has engineered and deployed <b>5+ production voice and chat agents</b> using Retell AI and GPT-4o, integrated with CRM and order-management systems.</p>\n<ul>\n<li><b>PIE (Packaging Intelligence Expert)</b>: an inbound chat and voice agent on the corporate website. It qualifies, segments and routes inbound leads within <b>10 minutes</b> of form submission, with no human in the first-response loop, targeting a <b>30%</b> reduction in inbound handling cost. Stack: Retell AI, VAPI, GPT-4o, n8n.</li>\n<li>Domestic call and chat agents (SIA / DIA) handle lead qualification and appointment booking.</li>\n<li>Voice, chat and RAG systems all read from the same lead record.</li>\n</ul>","links":[["Corporate website & PIE","work/corporate-site.html"]],"follow":["Has he built RAG systems?","What LLMs does he use?"]},{"id":"projects","title":"What he has built","keys":["projects","built","portfolio","work","case studies","platforms","products","shipped","examples"],"ask":["What has he built?","Show me his projects"],"answer":"<p>Main case studies:</p>\n<ul>\n<li><b>RFQ &amp; Pricing Platform</b>: AI-native quoting with a canonical data model (~7,900 SKUs), hierarchical markup and multi-tier approvals</li>\n<li><b>7-System AI Ecosystem / MarkAI</b>: connected lead, voice, ads, social, pipeline, RAG and escalation systems; 60% efficiency gain</li>\n<li><b>CAT AI</b>: a category-intelligence control plane; 80%+ productivity gain</li>\n<li><b>AI-Native Corporate Website &amp; PIE</b>: vibe-coded in Lovable, with a Retell AI chat and voice agent</li>\n</ul>\n<p>Also: <b>Nexus</b> (agentic control plane, in progress), <b>Avar Genie</b> (AI marketing platform, public beta), <b>Property Nex</b> (real-estate data platform, proof of concept), <b>Avar Systems</b> and <b>Avar Earth</b>.</p>","links":[["All work","index.html#work"]],"follow":["What is CAT AI?","What is Avar Genie?"]},{"id":"strength","title":"How he works","keys":["strength","strengths","approach","how he works","process","method","methodology","working style","problem solving","best at","superpower"],"ask":["What is his biggest strength?","How does he work?"],"answer":"<p>His biggest strength is turning a messy business problem into a working system:</p>\n<ol>\n<li><b>Analyse the problem</b>: start with the business problem, not the tool</li>\n<li><b>Understand the issues</b>: sit with the teams who live with it</li>\n<li><b>Join the dots</b>: connect the data, systems and people involved</li>\n<li><b>Plan the project</b>: scope it, sequence it, agree what success looks like</li>\n<li><b>Build a proof of concept</b>: prove it on real data before anyone commits</li>\n<li><b>Get the go-ahead, then build</b>: take it to production</li>\n</ol>\n<p>That is how the RFQ platform started from stakeholder discovery and a data model, and how Avar Systems runs every client engagement.</p>","links":[["How I work","index.html#approach"]],"follow":["Does he build proofs of concept?","What does he do at Avar Systems?"]},{"id":"poc","title":"Proofs of concept","keys":["poc","proof of concept","prototype","mvp","pilot","validate","experiment"],"ask":["Does he build proofs of concept?","How does he validate ideas?"],"answer":"<p>Yes. A proof of concept is a fixed step in how he works: prove the solution on real data, then get the final go-ahead before building for production.</p>\n<ul>\n<li>At <b>Avar Systems</b>, every client engagement moves from discovery to a POC on the client’s own data, then to delivery, within 4-week cycles.</li>\n<li><b>Property Nex</b> is a clickable POC of a real-estate data marketplace. It covers partner analysis, a data pipeline, a dataset module, a buyer marketplace and partner revenue share.</li>\n<li><b>Nexus</b> is being built as a working prototype of an agentic control plane.</li>\n</ul>","links":[["Property Nex POC","work/property-nex.html"]],"follow":["What is Property Nex?","What is Nexus?"]},{"id":"stack","title":"Tech stack","keys":["stack","tech stack","technologies","tools","tech","technology","platforms used","toolkit","skills","python","sql","programming","languages","tableau","coding skills"],"ask":["What is his tech stack?","What tools does he use?"],"answer":"<ul>\n<li><b>Models &amp; AI:</b> Anthropic Claude API, GPT-4o / OpenAI API, Google Gemini, RAG, multi-agent systems</li>\n<li><b>Voice, chat &amp; generative media:</b> Retell AI, VAPI, ElevenLabs, Dify, Higgsfield, Gemini and OpenAI image models</li>\n<li><b>Orchestration:</b> n8n (advanced), Make.com, Zapier, webhooks, REST APIs</li>\n<li><b>Cloud &amp; data:</b> AWS (EC2, S3, RDS), Google Cloud, Vercel, Supabase, SQL, Python, Tableau</li>\n<li><b>Business systems:</b> Salesforce, Zoho CRM, Odoo ERP, Shopify, Apollo.io, Apify, Tavily</li>\n<li><b>Build tooling:</b> Antigravity IDE, Cursor, Claude Code, Windsurf, Lovable, GitHub CI/CD, 21st.dev</li>\n</ul>","links":[["Tech stack","index.html#stack"]],"follow":["Which AI coding tools does he use?","What LLMs does he use?"]},{"id":"llms","title":"LLMs and models","keys":["llm","llms","model","models","claude","gpt","gpt-4o","openai","gemini","anthropic","which ai"],"ask":["What LLMs does he use?","Does he use Claude?"],"answer":"<p>His production systems use <b>Anthropic Claude</b> and <b>OpenAI GPT-4o</b>, with <b>Google Gemini</b> as well. He picks the model per task inside orchestrated workflows (n8n), rather than using one model for everything.</p>\n<p>For image generation he uses <b>Higgsfield</b> and the <b>Gemini and OpenAI image models</b>. All the imagery on the AI-native corporate website was generated that way. He holds Anthropic’s <b>Claude 101</b> and <b>Claude Platform 101</b> certificates.</p>","links":[["Certifications","index.html#certifications"]],"follow":["Which AI coding tools does he use?","What certifications does he have?"]},{"id":"ide","title":"AI coding tools","keys":["ide","coding","cursor","windsurf","antigravity","claude code","lovable","vibe coding","vibe coded","developer tools","code"],"ask":["Which AI coding tools does he use?","Does he use Cursor?"],"answer":"<p>He builds with AI-assisted development tools day to day:</p>\n<ul>\n<li><b>Antigravity IDE</b> and <b>Cursor</b> are his main IDEs, and he also knows <b>Windsurf</b></li>\n<li><b>Claude Code</b> for building production systems. The RFQ platform, CAT AI and Nexus were built with it.</li>\n<li><b>Lovable</b> for vibe coding. The AI-native corporate website was built in Lovable, on Supabase and Vercel.</li>\n<li><b>21st.dev</b> components for UI (CAT AI)</li>\n</ul>","links":[["Corporate website","work/corporate-site.html"],["CAT AI","work/cat-ai.html"]],"follow":["What is his tech stack?","What is CAT AI?"]},{"id":"cloud","title":"Cloud and data","keys":["cloud","aws","google cloud","gcp","vercel","supabase","database","infrastructure","deployment","devops","eventbridge"],"ask":["Does he know AWS?","What cloud does he use?"],"answer":"<p>He deploys on <b>AWS</b> (EC2, S3, RDS and managed services) and <b>Google Cloud</b>, with <b>Vercel</b> for web apps and <b>Supabase</b> as the shared data layer.</p>\n<ul>\n<li>The RFQ &amp; Pricing Platform runs in AWS production.</li>\n<li>The AI platform spans four regional domains on a unified Supabase backend, with n8n as the integration middleware.</li>\n<li>Nexus is designed around <b>AWS EventBridge</b> as the central integration hub.</li>\n</ul>","links":[["RFQ & Pricing Platform","work/rfq-platform.html"]],"follow":["Why a shared data layer?","What is Nexus?"]},{"id":"data-layer","title":"Single source of truth","keys":["data layer","single source of truth","data model","canonical","architecture principle","data architecture","shared data","master data"],"ask":["Why a shared data layer?","How does he approach data architecture?"],"answer":"<p>A recurring principle in his architecture is to <b>build the single source of truth first</b>.</p>\n<ul>\n<li>An ecosystem review he led showed that disconnected agents without a shared source of truth <b>cascade into failures</b>. So the 7-system ecosystem was built on one Supabase layer, with n8n orchestrating all seven systems and voice, chat and RAG reading the same lead record.</li>\n<li>In the RFQ platform, the <b>canonical data model</b> (36 sub-categories, 50 spec fields, ~7,900 SKUs) came first, so pricing and approvals sit on stable data instead of being hard-coded per SKU.</li>\n<li>Nexus uses the CRM as the system of record, synced both ways with every platform.</li>\n</ul>","links":[["RFQ & Pricing Platform","work/rfq-platform.html"]],"follow":["Tell me about the RFQ platform","Has he built AI agents?"]},{"id":"domains","title":"Industries","keys":["industries","industry","domain","domains","sectors","logistics","supply chain","ecommerce","packaging","procurement","retail"],"ask":["Which industries has he worked in?","Does he know logistics?"],"answer":"<p>His domain experience covers <b>logistics and supply chain</b>, <b>packaging and procurement</b>, <b>retail and eCommerce</b>, <b>B2B SaaS</b>, manufacturing and industrial procurement, <b>cross-border trade</b>, financial operations (order-to-cash, DSO reduction) and regulated-market compliance (EPR, ESG).</p>\n<p>Examples: international logistics markets at DTDC, a cross-border eCommerce SaaS at Whitley Ecom, a B2B packaging and procurement platform today, and a D2C brand (Avar Earth).</p>","links":[["Experience","index.html#experience"]],"follow":["What is his total experience?","Has he led teams?"]},{"id":"leadership","title":"Leadership","keys":["team","teams","lead","leadership","manage","managed","mentor","people","engineers","vendor","stakeholders","p&l"],"ask":["Has he led teams?","What leadership experience does he have?"],"answer":"<ul>\n<li>Led cross-functional and vendor engineering teams of <b>up to 11 engineers</b>, including an 11-agent external vendor engineering programme</li>\n<li>Owned <b>USD 3M–5M P&amp;L</b>; at DTDC, a USD 3M international P&amp;L with 20% year-over-year profit growth</li>\n<li>Scaled revenue <b>10x</b> (USD 500K to USD 5M) as co-founder of Whitley Ecom</li>\n<li>Drove market entry across <b>25 countries</b> and delivered go-to-market for 3 new international markets in 2026</li>\n<li>Runs discovery and C-suite conversations directly with client executives</li>\n</ul>","links":[["Experience","index.html#experience"]],"follow":["What are his biggest achievements?","What does he do at Avar Systems?"]},{"id":"fde","title":"Forward Deployed Engineer","keys":["forward deployed","fde","solutions architect","client facing","pre-sales","presales","consulting","customer facing"],"ask":["Why is he a Forward Deployed Engineer?","Is he client-facing?"],"answer":"<p>He works the way a Forward Deployed Engineer does: embedded with the business, close to the problem, and hands-on through to production.</p>\n<ul>\n<li>Runs discovery with commercial, procurement and marketing stakeholders himself</li>\n<li>Designs the architecture and builds with the team (Claude Code, Cursor, Antigravity)</li>\n<li>Ships to production and hands over, so client teams can run what he built</li>\n<li>Owns pre-sales and solutioning, including scoping, SOWs and commercials, at Avar Systems</li>\n</ul>","links":[["How I work","index.html#approach"]],"follow":["How does he work?","What does he do at Avar Systems?"]},{"id":"location","title":"Location","keys":["location","based","where","country","city","singapore","relocate","located"],"ask":["Where is he based?"],"answer":"<p>Abhishek is based in <b>Singapore</b> and has worked across APAC, the Middle East and the UK. He is looking for Senior AI Solutions Architect / Forward Deployed Engineer roles delivering enterprise AI transformation in Singapore.</p>","links":[["Contact","index.html#contact"]],"follow":["How can I contact him?","What role is he looking for?"]},{"id":"looking","title":"What he is looking for","keys":["looking for","open to","hire","hiring","available","availability","opportunity","next role","job search","interested","salary","compensation","notice period","notice","expected salary","package","ctc"],"ask":["What role is he looking for?","Is he open to opportunities?"],"answer":"<p>He is looking for <b>Senior AI Solutions Architect / Forward Deployed Engineer</b> roles delivering enterprise AI transformation programmes for consulting and enterprise clients in <b>Singapore</b>.</p>\n<p>For availability, notice period or anything contractual, it’s best to ask him directly.</p>","links":[["Contact","index.html#contact"]],"follow":["How can I contact him?","What are his biggest achievements?"]},{"id":"contact","title":"Contact","keys":["contact","email","reach","linkedin","get in touch","phone","call him","message","hire him"],"ask":["How can I contact him?","What is his email?"],"answer":"<p>The best ways to reach Abhishek:</p>\n<ul>\n<li>Email: <a href=\"mailto:abhishek87@live.in\">abhishek87@live.in</a></li>\n<li>LinkedIn: <a href=\"https://linkedin.com/in/abhishek-sharma\" target=\"_blank\" rel=\"noopener\">linkedin.com/in/abhishek-sharma</a></li>\n</ul>","links":[],"follow":["What role is he looking for?","Who is Abhishek?"]},{"id":"education","title":"Education","keys":["education","degree","university","studied","qualification","masters","bachelor","diploma","academic"],"ask":["What is his education?"],"answer":"<ul>\n<li><b>Diploma in Data Science</b>, Steinbeis Akademie, Germany (2022)</li>\n<li><b>Master of Arts, Marketing</b>, University of Bedfordshire, UK (2010)</li>\n<li><b>Bachelor of Arts (Honours), Economics</b>, University of Delhi, India (2009)</li>\n</ul>","links":[["Education","index.html#education"]],"follow":["What certifications does he have?","What is his total experience?"]},{"id":"certs","title":"Certifications","keys":["certification","certifications","certified","certificate","certificates","courses","credentials","coursera","udemy","google certificate"],"ask":["What certifications does he have?","Is he certified?"],"answer":"<ul>\n<li><b>AI &amp; ML:</b> Claude Platform 101 and Claude 101 (Anthropic); Generative AI Sprint, AI Generalist Accelerator (Outskill, 2025); Machine Learning A–Z (Udemy, 2025); Machine Learning with Python (IBM Cognitive Class, 2022)</li>\n<li><b>Data:</b> Google Data Analytics Professional Certificate (2021); Tableau Data Analyst / Specialist (2022)</li>\n<li><b>Security:</b> Google Cybersecurity Professional Certificate (2023); Cyber Security: Beginner to Expert (2023)</li>\n</ul>","links":[["Certifications","index.html#certifications"]],"follow":["What is his education?","What LLMs does he use?"]},{"id":"governance","title":"Responsible AI","keys":["governance","responsible ai","safety","human in the loop","guardrails","risk","compliance","approval","oversight","security"],"ask":["How does he handle AI governance?","Does he use human-in-the-loop?"],"answer":"<p>Guardrails are designed in, not added later:</p>\n<ul>\n<li>Outbound-facing systems launched with <b>human-in-the-loop review</b> before autonomous send, and the C-suite outreach pipeline runs on a draft-for-review model.</li>\n<li>In CAT AI, a person must approve before any vendor is contacted, and scores come with an explainable “why this score” trail.</li>\n<li>Avar Genie’s autopilot works within owner-set autonomy levels, spend and posting caps, and an escalation contact.</li>\n<li>Nexus puts every agent behind switches and a single kill switch.</li>\n</ul>\n<p>He also holds the Google Cybersecurity Professional Certificate.</p>","links":[["CAT AI","work/cat-ai.html"],["Nexus","work/nexus.html"]],"follow":["What is Nexus?","Has he built AI agents?"]},{"id":"automation","title":"Automation and n8n","keys":["n8n","automation","workflow","workflows","make.com","zapier","integration","integrations","pipeline","erp","crm"],"ask":["Does he know n8n?","What automation has he built?"],"answer":"<p>He is an advanced <b>n8n</b> practitioner and uses it as the orchestration layer across his systems:</p>\n<ul>\n<li>n8n orchestrates all seven systems in the AI ecosystem, so logic changes are made once, centrally</li>\n<li>Integration middleware across four regional domains on a unified Supabase backend</li>\n<li>At Avar Earth, an n8n layer syncs Odoo ERP finance reconciliation, inventory, social publishing and email triage (40% less admin work)</li>\n<li>An outbound pipeline with Apollo.io, Apify and Tavily that sends 10 personalised C-suite emails a day across 25+ countries</li>\n</ul>\n<p>He also works with Make.com and Zapier, and integrates Salesforce, Zoho CRM, Odoo ERP and Shopify.</p>","links":[["Tech stack","index.html#stack"]],"follow":["Has he built AI agents?","What is Avar Earth?"]},{"id":"anonymised","title":"Screenshots and Northwind","keys":["northwind","screenshots","real","masked","anonymised","anonymized","confidential","data privacy","x values","why x","fictional"],"ask":["Are the screenshots real?","What is Northwind?"],"answer":"<p>The case-study screenshots are <b>live captures of real production systems</b>.</p>\n<p>To protect the business, the employer is shown under a fictional brand, <b>Northwind Logistics</b>. Business figures are masked with “X”, and company and staff names are swapped for labels like “Client 01” or “Sales Rep A”. This was all done in the page itself before capture, with nothing cropped or blurred afterwards.</p>\n<p>The exception is <b>Property Nex</b>, a proof of concept that uses illustrative sample data.</p>","links":[["Selected work","index.html#work"]],"follow":["What has he built?","What is Property Nex?"]},{"id":"gtm","title":"Market expansion","keys":["market entry","expansion","international","gtm","go to market","countries","asean","business development","growth","revenue"],"ask":["Has he done market expansion?","What business experience does he have?"],"answer":"<ul>\n<li>Built the <b>ASEAN market-entry strategy</b> (Singapore hub, Johor spoke) and delivered go-to-market for <b>3 new international markets</b> in 2026</li>\n<li>Scaled a cross-border eCommerce SaaS from USD 500K to USD 5M in annual revenue (<b>10x</b>) over 5 years, across 25+ countries</li>\n<li>At DTDC, scaled the active country footprint from <b>12 to 25</b> with a USD 3M P&amp;L</li>\n<li>Advised international firms on Singapore and APAC market entry</li>\n</ul>","links":[["Experience","index.html#experience"]],"follow":["Has he led teams?","What is his total experience?"]},{"id":"hello","title":"Hello","keys":["hi","hello","hey","help","what can you do"],"ask":["Hi","What can I ask?"],"answer":"<p>Hi! I answer questions about Abhishek’s experience, projects, skills and results, using only what’s in this portfolio. Try one of the suggestions below.</p>","links":[],"follow":["What is his total experience?","What has he built?","What is his tech stack?"]},{"id":"rfq-platform","title":"RFQ & Pricing Platform","keys":["RFQ & Pricing Platform","Quoting & pricing platform"],"aliases":["rfq","quote","quoting","pricing platform","q-bot","qbot","markup","approvals","sku","quotation"],"ask":["What is RFQ & Pricing Platform?","Tell me about RFQ & Pricing Platform"],"answer":"<p><b>RFQ &amp; Pricing Platform</b> (Quoting &amp; pricing platform): Replaced a spreadsheet-driven RFQ and quoting process with one platform: a canonical product data model, hierarchical markup pricing and an embedded AI pricing assistant.</p><p><b>Problem:</b> Manual, spreadsheet-driven RFQ and quoting process across procurement and commercial teams — no canonical product data, no standard pricing logic, no approvals trail.</p><p><b>Impact:</b></p><ul><li>Replaced the manual quoting process end-to-end</li><li>Embedded Q-Bot, an in-console AI pricing assistant</li><li>Standardised markup logic across the commercial team</li></ul><p><b>Why it was built this way:</b> Canonical data model was built first so pricing/approvals logic could sit on top of stable spec data instead of being hard-coded per SKU.</p><p><b>Stack:</b> AWS, Claude Code, Antigravity IDE, GitHub, Supabase, Zoho CRM sync, GPT-4o/Claude</p>","links":[["Read the case study","work/rfq-platform.html"]],"follow":["What has he built?","How does he work?"]},{"id":"markai","title":"7-System AI Ecosystem / MarkAI","keys":["7-System AI Ecosystem / MarkAI","Connected AI operations"],"aliases":["markai","mark ai","7 system","7-system","seven systems","ecosystem","marketing platform","social studio","autopilot"],"ask":["What is 7-System AI Ecosystem / MarkAI?","Tell me about 7-System AI Ecosystem / MarkAI"],"answer":"<p><b>7-System AI Ecosystem / MarkAI</b> (Connected AI operations): Seven connected production systems (lead management, voice, ads, social, lead pipeline, RAG sales knowledge and escalation) running on one shared data layer.</p><p><b>Problem:</b> Lead management, inbound handling, marketing, and customer escalation ran as disconnected manual processes with no shared data layer — high headcount cost, slow response times.</p><p><b>Impact:</b></p><ul><li>60% operational efficiency gain</li><li>Elimination of 2+ FTE of manual workload</li></ul><p><b>Why it was built this way:</b> Started from one shared data layer (Supabase) rather than building seven independent systems — an earlier ecosystem review showed disconnected agents without a shared source of truth cascade into failures.</p><p><b>Stack:</b> GPT-4o, Claude, Retell AI, n8n, Supabase, Vercel, AWS</p>","links":[["Read the case study","work/markai.html"]],"follow":["What has he built?","How does he work?"]},{"id":"cat-ai","title":"CAT AI","keys":["CAT AI","Category intelligence control plane"],"aliases":["cat ai","catai","category intelligence","category","vendor verification","sourcing","demand intelligence"],"ask":["What is CAT AI?","Tell me about CAT AI"],"answer":"<p><b>CAT AI</b> (Category intelligence control plane): One control plane for deciding which packaging categories to launch: demand research, supply and vendor analysis, trial buying and scoring.</p><p><b>Problem:</b> New packaging-category opportunities were evaluated manually — demand signals, vendor capability, and margin potential lived in separate spreadsheets with no consistent scoring, slowing category launch decisions.</p><p><b>Impact:</b></p><ul><li>Over 80% improvement in productivity and market-signal coverage for category evaluation</li></ul><p><b>Why it was built this way:</b> Structured around the actual decision sequence a category lead follows — scan demand, check supply, validate vendors, trial-buy, score — rather than a generic dashboard.</p><p><b>Stack:</b> Antigravity IDE, Claude Code, 21st.dev</p>","links":[["Read the case study","work/cat-ai.html"]],"follow":["What has he built?","How does he work?"]},{"id":"corporate-site","title":"AI-Native Corporate Website & PIE Agent","keys":["AI-Native Corporate Website & PIE Agent","Vibe-coded web platform"],"aliases":["website","corporate site","corporate website","cognitive navigator"],"ask":["What is AI-Native Corporate Website & PIE Agent?","Tell me about AI-Native Corporate Website & PIE Agent"],"answer":"<p><b>AI-Native Corporate Website &amp; PIE Agent</b> (Vibe-coded web platform): The company’s global website, vibe-coded in Lovable, with an AI search navigator and PIE, a chat and voice agent on Retell AI, running on Supabase and Vercel.</p><ul><li>Vibe-coded in Lovable: every page, the navigation and the Cognitive Navigator, where visitors describe a packaging need in plain language.</li><li>PIE (Packaging Intelligence Expert), the chat and voice agent built on Retell AI. One widget offers text chat and a voice call.</li><li>In production, PIE qualifies, segments and routes inbound leads within 10 minutes of form submission, with no human in the first-response loop, targeting a 30% reduction in inbound handling cost.</li><li>Supabase as the database, deployed on Vercel.</li></ul><p><b>Stack:</b> Lovable, Retell AI, VAPI, GPT-4o, n8n, Supabase, Vercel, Higgsfield, Gemini, OpenAI image models</p>","links":[["Read the case study","work/corporate-site.html"]],"follow":["What has he built?","How does he work?"]},{"id":"nexus","title":"Nexus: Agentic Control Plane","keys":["Nexus: Agentic Control Plane","Agentic platform · work in progress"],"aliases":["nexus","control plane","kill switch","command center","eventbridge"],"ask":["What is Nexus: Agentic Control Plane?","Tell me about Nexus: Agentic Control Plane"],"answer":"<p><b>Nexus: Agentic Control Plane</b> (Agentic platform · work in progress): An agentic platform that connects the company’s AI agents and platforms and gives management one holistic view of them, with a single kill switch.</p><p>As the number of production agents and AI platforms grew (category intelligence, marketing, voice and chat agents, lead enrichment, RFQ, customer and vendor intelligence, collections), each one ran and reported on its own. Nexus is being built with Claude Code as the layer above them: it connects every platform, shows management what the whole estate is doing in one place, and puts all of it behind one kill switch. It is work in progress.</p><p><b>Design:</b></p><ul><li>One integration hub: every platform publishes and subscribes through AWS EventBridge rather than point-to-point links.</li><li>One source of truth: Zoho CRM is the system of record, synced both ways with every platform.</li><li>One management view: an executive dashboard and a topology map across all connected platforms and agents.</li><li>One control plane: any LLM, agent or connector can be switched off to isolate a problem, and a single kill switch stops everything.</li></ul>","links":[["Read the case study","work/nexus.html"]],"follow":["What has he built?","How does he work?"]},{"id":"property-nex","title":"Property Nex","keys":["Property Nex","Real-estate data platform · proof of concept"],"aliases":["property nex","property","real estate","real-estate","data marketplace","property data"],"ask":["What is Property Nex?","Tell me about Property Nex"],"answer":"<p><b>Property Nex</b> (Real-estate data platform · proof of concept): A proof of concept for a platform that turns scattered property data into data products that commercial companies can license.</p><p>Real-estate data sits with many different property owners, developers, brokers, agencies and facility managers, each holding it in its own format. It is hard to analyse and cannot be sold as a product, even though banks, insurers, retailers, logistics firms and investors need exactly this data to decide where to lend, insure, open and invest. Property Nex closes that gap: find the property clients who hold the data, bring it into one consistent model, and license it through a marketplace, with the property clients earning a share of every licence.</p><p><b>What the proof of concept covers:</b></p><ul><li>Data sources: property clients analysed and scored on volume, coverage, freshness and exclusivity, so only qualified partners become sources.</li><li>Data Studio: every source runs through one pipeline (ingest, clean, de-duplicate, normalise, enrich) into a canonical property data model, with personal data removed.</li><li>Dataset module: processed records packaged into licensable products such as a rental index, transaction history, commercial occupancy and industrial lease rates.</li><li>Marketplace: buyers preview a dataset and choose a snapshot, subscription or enterprise API licence.</li></ul>","links":[["Read the case study","work/property-nex.html"],["Open the POC","poc/property-nex/index.html"]],"follow":["What has he built?","How does he work?"]},{"id":"avar-systems","title":"Avar Systems","keys":["Avar Systems","End-to-end development firm"],"aliases":["avar systems","consulting","consultant","development firm","clients"],"ask":["What is Avar Systems?","Tell me about Avar Systems"],"answer":"<p><b>Avar Systems</b> (End-to-end development firm): An end-to-end development firm. I am the consultant between the customer and the build: I find the customer, understand the problem, prove the answer with a POC, then deliver the project.</p><p>Principal Consultant, January 2024 to present. Avar Systems designs, builds and deploys AI, automation and software for SME and mid-market businesses across logistics, eCommerce and professional services. I own the customer side of every engagement, from first conversation to handover.</p><p><b>How an engagement runs:</b></p><ul><li>Find the customer: identify businesses held back by manual, disconnected operations.</li><li>Talk to them: run discovery directly with the owners and executives who feel the problem.</li><li>Understand the problem: map where the process breaks and what fixing it is worth, then scope the engagement and commercials.</li><li>Create the POC: prove the solution on the customer’s own data before they commit.</li></ul>","links":[["Read the case study","work/avar-systems.html"]],"follow":["What has he built?","How does he work?"]},{"id":"avar-earth","title":"Avar Earth","keys":["Avar Earth","D2C brand · co-founder"],"aliases":["avar earth","d2c","vegan","footwear","shoes","shopify store"],"ask":["What is Avar Earth?","Tell me about Avar Earth"],"answer":"<p><b>Avar Earth</b> (D2C brand · co-founder): Public storefront for Avar Earth, a vegan footwear brand.</p><p>Co-Founder &amp; Head of Product and Technology, November 2023 to present. Full ownership of technology architecture, AI infrastructure, operations and P&amp;L. 8 points).</p>","links":[["Read the case study","work/avar-earth.html"]],"follow":["What has he built?","How does he work?"]},{"id":"avar-genie","title":"Avar Genie","keys":["Avar Genie","AI marketing platform · work in progress"],"aliases":["avar genie","genie","ai marketing","ads","social media","brand dna"],"ask":["What is Avar Genie?","Tell me about Avar Genie"],"answer":"<p><b>Avar Genie</b> (AI marketing platform · work in progress): An AI marketing platform that lets brand owners run their social media and ads without knowing how to write prompts.</p><p>Brand owners juggle tools, agencies and prompt-writing just to stay visible, and none of those fix it. Running social and paid ads well means knowing what to post, how to phrase it for each channel, where to put budget and how to read results beyond vanity metrics. I am building Avar Genie (now in public beta, work in progress) so a brand owner can go from a raw photo to published, on-brand posts and budgeted ads without writing a single prompt.</p><p><b>What the platform does:</b></p><ul><li>Brand DNA first: builds a profile of the brand from its website, visuals, tone and audience, so every post, ad, image and caption stays consistent across channels.</li><li>From brief to publish without prompts: start from a logo, a website or a blank canvas, and Genie fills in the rest.</li><li>One product, one campaign: a raw product photo becomes social posts with caption variants and targeted, budgeted ad variants.</li><li>Autopilot within guardrails: the owner sets the autonomy level, spend and posting caps and an escalation contact. Nothing publishes without approval unless the owner allows it.</li></ul>","links":[["Read the case study","work/avar-genie.html"]],"follow":["What has he built?","How does he work?"]},{"id":"exp-0","title":"Director of AI Solutions Architecture & International Expansion, Multi-region B2B packaging & procurement platform · Singapore","keys":["Multi-region B2B packaging & procurement platform","Director of AI Solutions Architecture & International Expansion"],"ask":["What did he do at Multi-region B2B packaging & procurement platform?"],"answer":"<p><b>Director of AI Solutions Architecture &amp; International Expansion</b>, Multi-region B2B packaging &amp; procurement platform · Singapore (Jan 2026 – Present)</p><ul><li>Architected and delivered a 7-system production AI ecosystem from discovery to deployment (GPT-4o, Anthropic Claude, Retell AI, n8n, Supabase, Vercel, AWS), delivering a 60% operational efficiency gain and eliminating 2+ FTE of manual workload.</li><li>Led end-to-end design and delivery of the RFQ &amp; Pricing Platform, an AI-native quotation, vendor RFQ and multi-tier approvals system: stakeholder discovery, solution architecture, a canonical data model (36 sub-categories, 50 specification fields, ~7,900 products) and production deployment on AWS.</li><li>Engineered and deployed 5+ production voice and chat agents (Retell AI, GPT-4o) for inbound handling, lead qualification and logistics escalation, integrated with CRM and order management and targeting a 30% reduction in inbound handling cost.</li><li>Led a cross-functional engineering delivery team, including an 11-agent external vendor engineering programme. Ran the architecture retrospective that traced cascading agent failures to a missing single-source-of-truth data layer, then drove the remediation roadmap.</li><li>Automated an outbound enterprise pipeline generating 10 personalised C-suite emails daily across 25+ countries (Apollo.io, Apify, Tavily, GPT-4o) under a human-in-the-loop review model.</li><li>Built the ASEAN market-entry strategy and delivered go-to-market for 3 new international markets in Q1–Q2 2026.</li></ul>","links":[["Experience","index.html#experience"]],"follow":["What is his total experience?","What are his biggest achievements?"]},{"id":"exp-1","title":"Principal Consultant, Avar Systems (independent practice) · Singapore","keys":["Avar Systems (independent practice)","Principal Consultant"],"ask":["What did he do at Avar Systems (independent practice)?"],"answer":"<p><b>Principal Consultant</b>, Avar Systems (independent practice) · Singapore (Jan 2024 – Present)</p><ul><li>Delivered production AI and automation solutions for 5+ enterprise and mid-market clients across logistics and eCommerce, reducing manual touchpoints 35–60% per engagement.</li><li>Ran pre-sales and solutioning directly with client executives, translating business problems into target-state architectures within 4-week delivery cycles.</li><li>Owned end-to-end technical delivery (architecture, build, cloud deployment, testing, documented handover and client-team enablement).</li></ul>","links":[["Experience","index.html#experience"]],"follow":["What is his total experience?","What are his biggest achievements?"]},{"id":"exp-2","title":"Co-Founder & Head of Product and Technology, Avar Earth · Singapore","keys":["Avar Earth","Co-Founder & Head of Product and Technology"],"ask":["What did he do at Avar Earth?"],"answer":"<p><b>Co-Founder &amp; Head of Product and Technology</b>, Avar Earth · Singapore (Nov 2023 – Present)</p><ul><li>Designed and deployed an n8n integration layer across Odoo ERP finance reconciliation, inventory, social publishing and email triage, reducing admin workload 40%.</li><li>Architected agentic fulfilment and logistics workflows with automated exception handling: 24% reduction in order lead time and a 3.8-point CSAT uplift.</li><li>Built an AI competitive-intelligence system scanning 15+ regional market signals daily.</li></ul>","links":[["Experience","index.html#experience"]],"follow":["What is his total experience?","What are his biggest achievements?"]},{"id":"exp-3","title":"Co-Founder and Head of Product, Whitley Ecom Pte Ltd · Singapore / International","keys":["Whitley Ecom Pte Ltd","Co-Founder and Head of Product"],"ask":["What did he do at Whitley Ecom Pte Ltd?"],"answer":"<p><b>Co-Founder and Head of Product</b>, Whitley Ecom Pte Ltd · Singapore / International (Apr 2018 – Oct 2023)</p><ul><li>Conceived, architected and launched GlobifyX, a SaaS platform for cross-border workflow optimisation: client operational lead times down 30%, first external enterprise client within 60 days of launch.</li><li>Scaled annual revenue from USD 500K to USD 5M (10x) over 5 years.</li><li>Directed operations and expansion across 25+ countries.</li></ul>","links":[["Experience","index.html#experience"]],"follow":["What is his total experience?","What are his biggest achievements?"]},{"id":"exp-4","title":"Senior Manager – International Markets, DTDC Express Ltd · International","keys":["DTDC Express Ltd","Senior Manager – International Markets"],"ask":["What did he do at DTDC Express Ltd?"],"answer":"<p><b>Senior Manager – International Markets</b>, DTDC Express Ltd · International (Jan 2015 – Apr 2018)</p><ul><li>Owned a USD 3M P&amp;L across the international portfolio, sustaining 20% year-over-year profit growth.</li><li>Scaled the active country footprint from 12 to 25 through distribution partnerships and enterprise account development.</li></ul>","links":[["Experience","index.html#experience"]],"follow":["What is his total experience?","What are his biggest achievements?"]}]};
/* Portfolio assistant: answers only from the knowledge base (window.__KB, generated at build time).
   Runs fully in the browser — no API, no network — so it also works when index.html is opened from disk. */
(function () {
  const KB = window.__KB;
  if (!KB || document.getElementById('pa-launch')) return;
  const root = new URL('.', document.currentScript ? document.currentScript.src : location.href).href;

  // ---------- retrieval ----------
  const STOP = new Set('a an the is are was were be been of to in on for with and or his he him her abhishek abhisheks sharma me you your i we do does did can could would should what which who whom how when where why tell about please show give any some this that these those there it its as at by from has have had into than then so if my our just also more most much many very'.split(' '));
  const norm = s => ' ' + s.toLowerCase().replace(/[’']/g, '').replace(/[^a-z0-9+#.&-]+/g, ' ').replace(/\s+/g, ' ').trim() + ' ';
  const SYN = { pocs: 'poc', llms: 'llm', prototypes: 'prototype', agent: 'agents', certs: 'certification', cert: 'certification', exp: 'experience', yrs: 'years', ai: 'ai', ml: 'machine' };
  const stem = w => { w = SYN[w] || w; return w.length > 4 ? w.replace(/(ing|ed|es|s)$/, '') : w; };
  const toks = s => norm(s).trim().split(' ').filter(w => w && !STOP.has(w)).map(stem);
  const strip = h => h.replace(/<[^>]+>/g, ' ').replace(/&amp;/g, '&');

  const docs = KB.entries.map(e => {
    const phrases = [...(e.keys || []), ...(e.aliases || [])].map(p => norm(p));
    const bag = (arr, w) => arr.forEach(t => (e._w[t] = Math.max(e._w[t] || 0, w)));
    e._w = {};
    bag(toks(strip(e.answer)), 0.6);
    bag(toks((e.ask || []).join(' ')), 2);
    bag(toks(e.title), 2.5);
    bag(toks((e.keys || []).join(' ')), 3);
    bag(toks((e.aliases || []).join(' ')), 3);
    e._phrases = phrases;
    return e;
  });
  const df = {};
  // Rarity is measured over the intent fields (keys, aliases, titles, example questions), not answer prose.
  docs.forEach(d => Object.keys(d._w).forEach(t => { if (d._w[t] >= 2) df[t] = (df[t] || 0) + 1; }));
  const seen = new Set(); docs.forEach(d => Object.keys(d._w).forEach(t => seen.add(t)));
  const idf = t => Math.log(1 + docs.length / (df[t] || 0.5));
  const maxIdf = Math.log(1 + docs.length / 1);

  function search(q) {
    const nq = norm(q), qt = toks(q);
    const scored = docs.map(d => {
      let s = 0;
      qt.forEach(t => { if (d._w[t]) s += d._w[t] * idf(t); });
      d._phrases.forEach(p => {
        if (!p.trim() || !nq.includes(p)) return;
        const base = d.aliases && d.aliases.map(norm).includes(p) ? 7 : 4;
        // Specific words (rare across the KB) earn the full bonus; generic ones like "experience" much less.
        const pt = toks(p), spec = pt.length ? Math.max(...pt.map(idf)) / maxIdf : (qt.length ? 0.4 : 1);
        s += base * (p.trim().includes(' ') ? 1.4 : spec * spec);
      });
      return [s, d];
    }).sort((a, b) => b[0] - a[0]);
    return scored;
  }

  // ---------- UI ----------
  const css = `
#pa-launch{position:fixed;right:22px;bottom:22px;z-index:9999;display:flex;align-items:center;gap:10px;background:#16233F;color:#fff;border:0;border-radius:999px;padding:12px 18px 12px 14px;font:600 14px/1 'Work Sans',system-ui,sans-serif;box-shadow:0 14px 34px -12px rgba(22,35,63,.55);cursor:pointer}
#pa-launch:hover{background:#1F5C3F}
#pa-launch svg{width:20px;height:20px}
#pa-panel{position:fixed;right:22px;bottom:22px;z-index:10000;width:min(400px,calc(100vw - 32px));height:min(600px,calc(100vh - 44px));background:#fff;border:1px solid #DFE4EB;box-shadow:0 30px 70px -25px rgba(22,35,63,.55);display:none;flex-direction:column;font:400 14.5px/1.55 'Work Sans',system-ui,sans-serif;color:#16233F}
#pa-panel.open{display:flex}
.pa-head{background:#16233F;color:#fff;padding:14px 16px;display:flex;align-items:flex-start;gap:10px}
.pa-head b{font:600 15px/1.3 'IBM Plex Sans',system-ui,sans-serif;display:block}
.pa-head span{font-size:12px;color:rgba(255,255,255,.68)}
.pa-x{margin-left:auto;background:none;border:0;color:#fff;font-size:22px;line-height:1;cursor:pointer;padding:0 2px}
.pa-log{flex:1;overflow-y:auto;padding:16px;display:flex;flex-direction:column;gap:12px;background:#F3F5F8}
.pa-msg{max-width:92%;padding:10px 13px;border:1px solid #DFE4EB;background:#fff}
.pa-msg.me{align-self:flex-end;background:#16233F;color:#fff;border-color:#16233F}
.pa-msg p{margin:0 0 8px}.pa-msg p:last-child{margin-bottom:0}
.pa-msg ul,.pa-msg ol{margin:4px 0 8px;padding-left:18px}.pa-msg li{margin:2px 0}
.pa-msg a{color:#1F5C3F}
.pa-links{display:flex;flex-wrap:wrap;gap:6px;margin-top:8px}
.pa-links a{font:500 12.5px/1 'IBM Plex Mono',ui-monospace,monospace;text-decoration:none;border:1px solid #1F5C3F;color:#1F5C3F;padding:5px 8px}
.pa-chips{display:flex;flex-wrap:wrap;gap:6px;padding:10px 16px 0;background:#fff;border-top:1px solid #DFE4EB}
.pa-chip{background:#F3F5F8;border:1px solid #DFE4EB;color:#16233F;font:500 12.5px/1.2 'Work Sans',system-ui,sans-serif;padding:6px 9px;cursor:pointer;text-align:left}
.pa-chip:hover{border-color:#1F5C3F;color:#1F5C3F}
.pa-form{display:flex;gap:8px;padding:10px 16px 14px;background:#fff}
.pa-form input{flex:1;border:1px solid #DFE4EB;padding:10px 12px;font:inherit;color:#16233F;outline:none}
.pa-form input:focus{border-color:#16233F}
.pa-form button{background:#1F5C3F;color:#fff;border:0;padding:0 14px;font:600 13.5px/1 'Work Sans',system-ui,sans-serif;cursor:pointer}
.pa-note{font-size:11.5px;color:#69738A;padding:0 16px 10px;background:#fff}
.pa-typing{color:#69738A;font-size:13px}
@media (max-width:520px){#pa-launch span{display:none}#pa-launch{padding:13px}#pa-panel{right:16px;bottom:16px}}
@media print{#pa-launch,#pa-panel{display:none!important}}`;
  const style = document.createElement('style'); style.textContent = css; document.head.appendChild(style);

  const launch = document.createElement('button');
  launch.id = 'pa-launch'; launch.type = 'button'; launch.setAttribute('aria-label', 'Ask about Abhishek');
  launch.innerHTML = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M12 3l1.8 4.7L18.5 9.5l-4.7 1.8L12 16l-1.8-4.7L5.5 9.5l4.7-1.8z"/><path d="M19 15l.8 2.2L22 18l-2.2.8L19 21l-.8-2.2L16 18l2.2-.8z"/></svg><span>Ask about Abhishek</span>';
  const panel = document.createElement('section');
  panel.id = 'pa-panel'; panel.setAttribute('role', 'dialog'); panel.setAttribute('aria-label', 'Portfolio assistant');
  panel.innerHTML = `<div class="pa-head"><div><b>Ask about Abhishek</b><span>Answers only from this portfolio’s knowledge base</span></div><button class="pa-x" aria-label="Close">×</button></div>
<div class="pa-log" aria-live="polite"></div><div class="pa-chips"></div>
<form class="pa-form"><input type="text" placeholder="e.g. What is his total experience?" aria-label="Your question" autocomplete="off"><button type="submit">Ask</button></form>
<div class="pa-note">No AI model or tracking. Matches your question to curated answers.</div>`;
  document.body.append(launch, panel);
  const log = panel.querySelector('.pa-log'), chips = panel.querySelector('.pa-chips'), input = panel.querySelector('input');
  const esc = s => s.replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' })[c]);
  const fix = h => h.replace(/href="(?!https?:|mailto:|#)([^"]+)"/g, (m, p) => `href="${root}${p}"`);

  function add(html, me) {
    const d = document.createElement('div'); d.className = 'pa-msg' + (me ? ' me' : ''); d.innerHTML = html;
    log.appendChild(d); log.scrollTop = log.scrollHeight; return d;
  }
  function setChips(list) {
    chips.innerHTML = '';
    list.slice(0, 4).forEach(q => { const b = document.createElement('button'); b.type = 'button'; b.className = 'pa-chip'; b.textContent = q; b.onclick = () => ask(q); chips.appendChild(b); });
  }
  function answer(q) {
    const r = search(q);
    const [s, best] = r[0];
    if (s < 2.2) {
      return { html: `<p>I don’t have that in Abhishek’s portfolio, so I won’t guess. I can answer questions about his experience, projects, results, skills, tech stack, certifications and how to contact him.</p><p>For anything else, email <a href="mailto:${esc(KB.email)}">${esc(KB.email)}</a>.</p>`, follow: KB.starters };
    }
    let html = best.answer;
    // Be explicit when the question names something the portfolio never mentions.
    const unknown = norm(q).trim().split(' ').filter(w => w && !STOP.has(w) && !seen.has(stem(w)) && w.length > 2 && !/^\d+$/.test(w));
    if (unknown.length && s < 7) html = `<p><i>“${esc(unknown.join(', '))}” isn’t mentioned in Abhishek’s portfolio, so I can’t confirm it. Here’s the closest related information:</i></p>` + html;
    const links = (best.links || []).map(([l, h]) => `<a href="${h}">${esc(l)} →</a>`).join('');
    if (links) html += `<div class="pa-links">${links}</div>`;
    const related = r.slice(1, 3).filter(([s2, d]) => s2 > Math.max(2.2, s * 0.72) && d.id !== best.id).map(([, d]) => d.ask && d.ask[0]).filter(Boolean);
    return { html: fix(html), follow: [...related, ...(best.follow || [])].filter((x, i, a) => a.indexOf(x) === i && norm(x) !== norm(q)) };
  }
  function ask(q) {
    q = q.trim(); if (!q) return;
    add(esc(q), true); input.value = '';
    const t = add('<span class="pa-typing">…</span>');
    setTimeout(() => { const a = answer(q); t.innerHTML = a.html; setChips(a.follow.length ? a.follow : KB.starters); log.scrollTop = Math.max(0, t.offsetTop - log.offsetTop - 60); }, 280);
  }
  let greeted = false;
  function open() {
    panel.classList.add('open'); launch.style.display = 'none';
    if (!greeted) { greeted = true; add(`<p>Hi, I can answer questions about Abhishek’s <b>experience, projects, results, skills and tech stack</b>, straight from this portfolio.</p>`); setChips(KB.starters); }
    input.focus();
  }
  function close() { panel.classList.remove('open'); launch.style.display = ''; launch.focus(); }
  launch.onclick = open;
  panel.querySelector('.pa-x').onclick = close;
  panel.addEventListener('keydown', e => { if (e.key === 'Escape') close(); });
  panel.querySelector('form').onsubmit = e => { e.preventDefault(); ask(input.value); };
  window.__paAnswer = q => answer(q); // for testing
  window.__paScore = q => search(q).slice(0, 2).map(([s, d]) => d.id + ':' + s.toFixed(1));
})();
